                            name: getNativeFlowName(innerMessage)
                        }
                    }
                ]
            }
        ]
    });
    logger.debug({ jid }, 'adding native flow business node');
}
const buttonType = getButtonType(innerMessage);
if (!isNewsletter && buttonType) {
    stanza.content.push({
